"void updateParameters(in vec2 position, in vec2 otherPos, in vec2 otherVel, inout vec2 center, inout float numNeighborsCenter, inout vec2 move, inout vec2 avg, inout float numNeighborsAverage){" +
"  float d = length(position - otherPos);" + // otherとの距離
"  if(d < uVisualRange){" + //otherが見えている場合
"    center += otherPos;" +
"    numNeighborsCenter += 1.0;" + // 見えている鳥の数を数える
"    avg += otherVel;" +
"    numNeighborsAverage += 1.0;" +
"  }" +
"  if(d < uMinDistance){" + // otherが近づきすぎたら
"    move += position - otherPos;" + // 位置の差をmoveに足す(引き離す)
"  }" +
"}" +
// メインコード
"void main(){" +
"  vec2 st = gl_FragCoord.xy;" +
// st.y == 0.5のところを横に見ていく感じ
// st.y < 1.0の場合に位置更新。256.0をマジックナンバーで・・うん。
