"  float numNeighborsCenter = 0.0;" +
"  vec2 move = vec2(0.0);" +
"  vec2 avg = vec2(0.0);" +
"  float numNeighborsAverage = 0.0;" +
// otherごとの計算で上記の5つが更新される
