  headTex = new p5.Texture(_gl, arrowGr);
}

function draw(){
  const start = performance.now();

  // ここで位置と速度を更新(swapもここで済ませてしまっている)
  moveRendering();

  _node.bindFBO(null)
       .setViewport(0, 0, width, height);
  clear();

  // 背景
  _node.use('bg', 'board')
       .setTexture('uTex', bgTex.glTex, 3)
       .setUniform('uResolution', [width, height])
       .drawArrays(gl.TRIANGLE_STRIP)
       .clear();

  // ここからboids描画
  // step.
  properFrameCount++;
  ambient = _HSV((properFrameCount % 360) / 360, 0.8, 1);

  // blendの有効化
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.ONE, gl.ONE);

  _node.use('draw', 'boids')
       .setFBO('uTex', 'boids')
       .setAttribute() // 忘れてた。もういや。
       .setTexture('uHead', headTex.glTex, 4)
       .setUniform('uTexSize', [TEX_SIZE_X, TEX_SIZE_Y])
       .setUniform('uPointScale', 32.0)
       .setUniform('uAmbient', [ambient.r, ambient.g, ambient.b])
       .bindIndexBuffer()
       .setUniform('uIsPoint', false) // 軌跡描画用分岐
       .drawElements(gl.LINES)
       .setUniform('uIsPoint', true) // ヘッド描画用分岐
       .drawArrays(gl.POINTS)
       .clear()
       .flush();

  gl.disable(gl.BLEND); // blendを消しておく

  const end = performance.now();
  const performanceRatio = (end - start) * 60 / 1000;

  bg.image(base, 0, 0);
  bg.text(performanceRatio.toFixed(3), 20, 20);
  bgTex.update(); // 忘れずに！！
}

